use rhwp::DocumentCore;
use serde_json::{Value,json};
fn fixture(tabs:bool)->DocumentCore{let mut d=DocumentCore::new_empty();d.create_blank_document_native().unwrap();for(p,t)in (if tabs{vec!["A","TITLE\tSCORE","A\t20","B\t3","C\t-2","TAIL"]}else{vec!["A","TITLE","A20","B3","C-2","TAIL"]}).iter().enumerate(){if p>0{let n=d.get_paragraph_length_native(0,p-1).unwrap();d.split_paragraph_native(0,p-1,n,None).unwrap();}d.insert_text_native(0,p,0,t).unwrap();}d}
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn equal(a:&Value,b:&Value,p:&str){match(a,b){(Value::Number(a),Value::Number(b))=>{let(x,y)=(a.as_f64().unwrap(),b.as_f64().unwrap());let coordinate=p.rsplit('/').next().is_some_and(|k|["x","y","w","h"].contains(&k))||p.contains("/charX/");assert!(if coordinate{(x-y).abs()<=0.2}else{x==y},"{p}: {x}->{y}");},(Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{p}");for(i,(a,b))in a.iter().zip(b).enumerate(){equal(a,b,&format!("{p}/{i}"));}},(Value::Object(a),Value::Object(b))=>{assert_eq!(a.keys().collect::<Vec<_>>(),b.keys().collect::<Vec<_>>(),"{p}");for(k,a)in a{equal(a,&b[k],&format!("{p}/{k}"));}},_=>assert_eq!(a,b,"{p}")}}
fn cycles(d:&DocumentCore){let before=state(d);let source=serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap();for f in["hwp","hwpx"]{let mut next=None;for _ in 0..2{let s=next.as_ref().unwrap_or(d);let artifact=if f=="hwp"{s.export_hwp_with_adapter_snapshot_with_report().unwrap()}else{s.export_hwpx_native_with_report().unwrap()};assert!(artifact.content_loss().is_empty());let r=DocumentCore::from_bytes(&artifact.into_bytes()).unwrap();equal(&before,&state(&r),"pages");assert_eq!(source,serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap(),"save may not mutate source");next=Some(r);}}}
#[test]fn tab_spacing_before_is_visible_immediately_and_preserves_both_codecs(){for gap in[75,283,1000]{let mut d=fixture(true);let before=state(&d);let bindings=serde_json::to_value(&d.document().sections[0].paragraphs.iter().map(|p|(&p.text,&p.char_shapes,p.style_id)).collect::<Vec<_>>()).unwrap();d.apply_para_format_native(0,3,&format!(r#"{{"alignment":"center","spacingBefore":{gap}}}"#)).unwrap();let live=state(&d);let y=|v:&Value|v[0]["text"]["runs"][3]["y"].as_f64().unwrap();assert!(y(&live)>y(&before),"gap {gap} must affect the live line");assert_eq!(bindings,serde_json::to_value(&d.document().sections[0].paragraphs.iter().map(|p|(&p.text,&p.char_shapes,p.style_id)).collect::<Vec<_>>()).unwrap());cycles(&d);}}
#[test]fn tab_spacing_after_moves_following_lines_and_preserves_both_codecs(){for gap in[75,283,1000]{let mut d=fixture(true);d.apply_para_format_native(0,3,&format!(r#"{{"spacingAfter":{gap}}}"#)).unwrap();cycles(&d);}}
#[test]fn ordinary_spacing_noop_and_unrelated_style_do_not_gain_tab_reflow(){let mut d=fixture(false);d.apply_para_format_native(0,3,r#"{"spacingBefore":283}"#).unwrap();cycles(&d);let mut d=fixture(true);let before=serde_json::to_vec(&d.document().sections[0].paragraphs[3].line_segs).unwrap();d.apply_para_format_native(0,3,r#"{"spacingBefore":0,"spacingAfter":0,"alignment":"center"}"#).unwrap();assert_eq!(before,serde_json::to_vec(&d.document().sections[0].paragraphs[3].line_segs).unwrap());cycles(&d);}
#[test]fn tab_spacing_snapshot_undo_redo_restores_exact_live_and_saved_state(){let mut d=fixture(true);let before=state(&d);let bytes=d.export_hwpx_native_with_report().unwrap().into_bytes();let undo=d.save_snapshot_native();d.apply_para_format_native(0,3,r#"{"spacingBefore":283,"spacingAfter":75}"#).unwrap();let edited=state(&d);let redo=d.save_snapshot_native();cycles(&d);d.restore_snapshot_native(undo).unwrap();equal(&before,&state(&d),"pages");assert_eq!(bytes,d.export_hwpx_native_with_report().unwrap().into_bytes());d.restore_snapshot_native(redo).unwrap();equal(&edited,&state(&d),"pages");cycles(&d);}

#[test]fn resolved_real_tab_payload_does_not_enter_the_new_spacing_only_reflow(){let mut d=fixture(true);let mut doc=d.document().clone();doc.sections[0].paragraphs[3].tab_extended=vec![[4000,0,0,0,0,0,9]];d.set_document(doc);let before=serde_json::to_vec(&d.document().sections[0].paragraphs[3].line_segs).unwrap();d.apply_para_format_native(0,3,r#"{"spacingBefore":283}"#).unwrap();assert_eq!(before,serde_json::to_vec(&d.document().sections[0].paragraphs[3].line_segs).unwrap(),"resolved tab imported LINE_SEG lifecycle stays outside this candidate");assert_eq!(d.document().sections[0].paragraphs[3].tab_extended,vec![[4000,0,0,0,0,0,9]]);}
